{
  "title": "Company VPN Troubleshooting Checklist",
  "generated": "2026-08-03",
  "version": "2.0 (Post-Migration)",
  "contradictions_resolved": [
    "kb_001 (FortiClient) superseded by kb_006 (GlobalProtect migration)"
  ],
  "sources": [
    "kb_001",
    "kb_006",
    "kb_007"
  ],
  "troubleshooting_steps": [
    {
      "step": 1,
      "title": "Verify VPN Client",
      "description": "Ensure you are using GlobalProtect VPN client (Palo Alto Networks). FortiClient is no longer supported after March 1, 2026.",
      "source": "kb_006"
    },
    {
      "step": 2,
      "title": "Download/Install GlobalProtect",
      "description": "Download GlobalProtect from https://vpn.company.com/downloads",
      "source": "kb_006"
    },
    {
      "step": 3,
      "title": "Connect to VPN Server",
      "description": "Open GlobalProtect and connect using server address: vpn.company.com",
      "source": "kb_001, kb_006"
    },
    {
      "step": 4,
      "title": "Authentication",
      "description": "Log in with your company email account and password. Password must be changed every 90 days. If authentication fails, reset password at https://password.company.com",
      "source": "kb_001, kb_005"
    },
    {
      "step": 5,
      "title": "Select Connection Mode",
      "description": "Select [Full Tunnel Mode] to connect",
      "source": "kb_001"
    },
    {
      "step": 6,
      "title": "Troubleshoot Connection Timeout",
      "description": "Check your network connection and ensure the firewall is not blocking VPN port (443). Refer to firewall settings in VPN Connection Guide.",
      "source": "kb_001, kb_007"
    },
    {
      "step": 7,
      "title": "Troubleshoot Frequent Disconnections",
      "description": "Switch to 5GHz WiFi or use a wired connection.",
      "source": "kb_007"
    },
    {
      "step": 8,
      "title": "Troubleshoot Authentication Failure",
      "description": "Confirm your password has not expired. You can reset it at https://password.company.com or contact IT hotline ext.8888.",
      "source": "kb_001, kb_005"
    },
    {
      "step": 9,
      "title": "Troubleshoot Intranet Access Issues",
      "description": "Try disconnecting and reconnecting. If issues persist, contact IT hotline ext.8888.",
      "source": "kb_001"
    },
    {
      "step": 10,
      "title": "Verify MFA",
      "description": "MFA is mandatory for all systems. Recommended: Microsoft Authenticator. Backup method: SMS verification code.",
      "source": "kb_005"
    }
  ],
  "contact_info": {
    "it_hotline": "ext.8888",
    "password_reset": "https://password.company.com",
    "vpn_downloads": "https://vpn.company.com/downloads"
  },
  "important_notes": [
    "VPN password syncs with your email password and must be changed every 90 days",
    "Special VPN permissions must be requested in advance for overseas business trips",
    "kb_006 migration notice takes priority over kb_001 FortiClient guide",
    "FortiClient will no longer be supported starting March 1, 2026"
  ]
}
